actions.script:
invoiceMap = {}
const cf = ec.entity.conditionFactory
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
    const all = !!vis.allProjects
    let scope = all ? null : Array.from(vis.visibleProjectIds || [])
    if (rootWorkEffortId) { if (scope && !scope.includes(rootWorkEffortId)) return; scope = [rootWorkEffortId] }
    if (scope && !scope.length) return
    const ids = invoiceIds != null ? Array.from(invoiceIds).map(String).filter((id) => id) : null
    if (ids != null && !ids.length) return
    const add = (invoiceId, projectId, kind) => {
        if (!invoiceId || !projectId) return
        if (scope && !scope.includes(projectId)) return
        const entry = invoiceMap[invoiceId] || (invoiceMap[invoiceId] = {kind: kind, projectIds: []})
        if (kind === 'worker' || (kind === 'client' && entry.kind === 'expense')) entry.kind = kind
        if (!entry.projectIds.includes(projectId)) entry.projectIds.push(projectId)
    }
    const rootOf = (row) => row.workEffortTypeEnumId === 'WetProject' ? row.workEffortId : (row.rootWorkEffortId || null)
    const scoped = (field) => {
        const conds = [cf.makeCondition(field, 'is-not-null', null)]
        if (ids) conds.push(cf.makeCondition(field, 'in', ids))
        if (scope) conds.push(cf.makeCondition([cf.makeCondition('rootWorkEffortId', 'in', scope), cf.makeCondition('workEffortId', 'in', scope)], 'or'))
        return cf.makeCondition(conds, 'and')
    }
    // the time billed: client invoices by invoiceId, worker invoices by vendorInvoiceId
    for (const [field, kind] of [['invoiceId', 'client'], ['vendorInvoiceId', 'worker']]) {
        const seen = new Set()
        for (const row of ec.entity.find('mantle.work.time.TimeEntryAndWorkEffort').condition(scoped(field)).selectField(field).selectField('workEffortId')
                .selectField('rootWorkEffortId').selectField('workEffortTypeEnumId').limit(50000).list()) {
            const key = row[field] + ' ' + rootOf(row)
            if (seen.has(key)) continue
            seen.add(key)
            add(row[field], rootOf(row), kind)
        }
    }
    // the invoices linked to a project or its items
    let links = ec.entity.find('mantle.work.effort.WorkEffortInvoice')
    if (ids) links = links.condition('invoiceId', 'in', ids)
    const linkRows = Array.from(links.limit(20000).list())
    const efforts = {}
    const effortIds = Array.from(new Set(linkRows.map((row) => row.workEffortId)))
    for (let i = 0; i < effortIds.length; i += 1000) for (const row of ec.entity.find('mantle.work.effort.WorkEffort')
            .condition('workEffortId', 'in', effortIds.slice(i, i + 1000)).selectField('workEffortId').selectField('rootWorkEffortId')
            .selectField('workEffortTypeEnumId').list()) efforts[row.workEffortId] = row
    const clients = {}
    const clientOf = (projectId) => {
        if (!(projectId in clients)) clients[projectId] = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', projectId)
                .condition('roleTypeId', 'in', ['Customer', 'CustomerBillTo']).list()).map((row) => row.partyId)
        return clients[projectId]
    }
    const linkInvoiceIds = Array.from(new Set(linkRows.map((row) => row.invoiceId)))
    const toParty = {}
    for (let i = 0; i < linkInvoiceIds.length; i += 1000) for (const row of ec.entity.find('mantle.account.invoice.Invoice')
            .condition('invoiceId', 'in', linkInvoiceIds.slice(i, i + 1000)).selectField('invoiceId').selectField('toPartyId').list()) toParty[row.invoiceId] = row.toPartyId
    for (const link of linkRows) {
        const effort = efforts[link.workEffortId]
        if (!effort) continue
        const projectId = rootOf(effort)
        if (!projectId) continue
        add(link.invoiceId, projectId, clientOf(projectId).includes(toParty[link.invoiceId]) ? 'client' : 'expense')
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

isClient = false; invoiceMap = {}; clientProjectIds = []; shareHoursProjectIds = []
if (!ec.user.userId || !ec.user.hasPermission('PROJECT_CLIENT')) return
isClient = true
const shownStatuses = ['InvoiceSent', 'InvoiceAcked', 'InvoicePmtRecvd']
ec.message.pushErrors()
try {
    const info = ec.service.sync().name('mantle.work.ProjectServices.get#ClientProjectInfo').call() || {}
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    const projects = Array.from(info.clientProjectIds || []).map(String)
    const parties = Array.from(info.clientPartyIds || []).map(String)
    if (!projects.length || !parties.length) return
    if (rootWorkEffortId && !projects.includes(String(rootWorkEffortId))) return
    const found = ec.service.sync().name('ironstone.projects.BillingServices.get#InvoiceProjects').parameters({invoiceIds: invoiceIds ?? null,
        rootWorkEffortId: rootWorkEffortId || null}).call()?.invoiceMap || {}
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    const ids = Object.keys(found).filter((id) => found[id].kind === 'client')
    const wasDisabled = ec.artifactExecution.disableAuthz()
    try {
        for (let i = 0; i < ids.length; i += 1000) for (const inv of ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', 'in', ids.slice(i, i + 1000))
                .selectField('invoiceId').selectField('toPartyId').selectField('statusId').list()) {
            if (!inv.toPartyId || !parties.includes(String(inv.toPartyId)) || !shownStatuses.includes(inv.statusId)) continue
            const own = Array.from(found[inv.invoiceId].projectIds || []).filter((id) => projects.includes(String(id)))
            if (!own.length) continue
            invoiceMap[inv.invoiceId] = {kind: 'client', projectIds: own}
        }
    } finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
    clientProjectIds = projects
    shareHoursProjectIds = Array.from(info.shareHoursProjectIds || []).map(String).filter((id) => projects.includes(id))
} catch (err) {
    ec.logger.error(`Invoices of client user ${ec.user.userId} not read, none shown: ${err && err.message ? err.message : err}`)
    invoiceMap = {}; clientProjectIds = []; shareHoursProjectIds = []
} finally {
    ec.message.clearErrors()
    ec.message.popErrors()
}

canView = false; invoice = null; kind = null; projectIds = []; clientView = false; shareHoursProjectIds = []
if (ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')) {
    // a client reads its own sent invoices and changes none (impl-projects.md P10b)
    if (need === 'view' || need === 'none') {
        const client = ec.service.sync().name('ironstone.projects.BillingServices.get#ClientInvoices').parameters({invoiceIds: [invoiceId]}).call() || {}
        const found = (client.invoiceMap || {})[invoiceId]
        const row = found ? ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).disableAuthz().one() : null
        if (row) { canView = true; clientView = true; invoice = row.getMap(); kind = 'client'; projectIds = found.projectIds
            shareHoursProjectIds = Array.from(client.shareHoursProjectIds || []) }
    }
    if (!canView && need !== 'none') ec.message.addError(ec.resource.expand('Invoice ${invoiceId} is not available', '', {invoiceId}))
    return
}
const money = ec.service.sync().name('ironstone.projects.BillingServices.check#Money').parameters({need: 'none'}).call()?.managesMoney
if (money) {
    const row = ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).disableAuthz().one()
    const found = row ? (ec.service.sync().name('ironstone.projects.BillingServices.get#InvoiceProjects').parameters({invoiceIds: [invoiceId]}).call()?.invoiceMap || {})[invoiceId] : null
    if (row && found) { canView = true; invoice = row.getMap(); kind = found.kind; projectIds = found.projectIds }
}
if (!canView && need !== 'none') ec.message.addError(ec.resource.expand('Invoice ${invoiceId} is not available', '', {invoiceId}))

draft = null
ec.service.sync().name('ironstone.projects.BillingServices.check#Money').call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'manage'}).call()
if (ec.message.hasError()) return
const L = (text) => ec.l10n.localize(text)
const out = ec.service.sync().name('mantle.work.ProjectServices.get#UnbilledSummary').parameters({workEffortId: workEffortId, withEntries: true}).call() || {}
if (ec.message.hasError()) return
const row = Array.from(out.projectList || [])[0]
const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).disableAuthz().one()
const settingsOut = ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: workEffortId}).call() || {}
const settings = settingsOut.settings || {}
const defaults = ec.service.sync().name('ironstone.projects.BillingServices.get#BillingSettings').parameters({organizationPartyId: settingsOut.organizationPartyId || null}).call()?.defaults || {}
const groupings = {PerEntry: 'entry', PerWorker: 'worker', OneLine: 'all'}
const uom = row?.currencyUomId || 'USD'
const money = (value) => value == null ? '' : ec.l10n.formatCurrency(value, uom)
const hoursText = (value) => value == null ? '' : ec.l10n.format(value, '#,##0.##')
const entries = Array.from(row?.entryList || [])
const ready = entries.filter((entry) => entry.ready)
const draftDays = ec.resource.script('component://mr-mantle/service/mantle/account/InvoiceWorkflowLib.js')
    .invoiceCalendarDays(Array.from(row?.draftInvoiceList || []).map(inv => inv.invoiceId))
draft = {workEffortId: workEffortId, projectName: project?.workEffortName || workEffortId, clientPartyId: row?.clientPartyId || null, clientName: row?.clientName || '',
    canInvoice: !!row?.canInvoice, cannotReason: row ? (row.cannotReason || '') : L('Nothing to invoice'),
    entryGrouping: groupings[settings.WstInvoiceGrouping] || 'entry', settlementTermId: defaults.settlementTermId || '',
    readyHoursText: row ? hoursText(row.readyHours) : '0', readyAmountText: row ? money(row.readyAmount) : money(toDecimal(0)),
    waitingHoursText: row ? hoursText(toDecimal(row.waitingHours).add(row.openHours)) : '0', currencyUomId: uom,
    milestoneOptions: Array.from(row?.milestoneDueList || []).map((share) => ({key: share.workEffortId + ':' + share.orderId + ':' + share.orderItemSeqId,
        text: [share.milestoneName, share.invoicePercent != null ? ec.l10n.format(share.percent, '#,##0.##') + '% ' + L('of') + ' ' + (share.itemDescription || share.orderId)
            : (share.itemDescription || share.orderId), money(share.amount)].join(' · ')})),
    selectedMilestoneIds: Array.from(row?.milestoneDueList || []).map((share) => share.workEffortId + ':' + share.orderId + ':' + share.orderItemSeqId),
    milestoneDueText: row?.milestoneDueCount ? money(row.milestoneDueAmount) : '',
    entryOptions: ready.map((entry) => ({key: entry.timeEntryId, missingRate: entry.missingRate,
        text: [ec.l10n.format(new Date(entry.fromDate), 'MMM d'), entry.personName, (entry.workEffortId === workEffortId ? '' : entry.workEffortId + ' ') + entry.workEffortName,
            hoursText(entry.hours) + ' h', entry.missingRate ? L('no rate') : money(entry.amount)].filter((part) => part).join(' · ')
            + (entry.comments ? ' — ' + entry.comments.substring(0, 60) : '')})),
    selectedIds: ready.filter((entry) => !entry.missingRate).map((entry) => entry.timeEntryId),
    draftOptions: Array.from(row?.draftInvoiceList || []).map((inv) => ({key: inv.invoiceId,
        text: inv.invoiceId + ' · ' + (draftDays[inv.invoiceId]?.invoiceDay || (inv.invoiceDate != null ? ec.l10n.format(new Date(inv.invoiceDate), 'MMM d, yyyy') : '')) + ' · ' + money(inv.invoiceTotal)}))}

const L = (text) => ec.l10n.localize(text)
itemCount = 0
ec.service.sync().name('ironstone.projects.BillingServices.check#Money').call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'manage'}).call()
if (ec.message.hasError()) return
if (!['entry', 'worker', 'all'].includes(entryGrouping)) { ec.message.addError(L('Group by entry, by worker or in one line')); return }
const out = ec.service.sync().name('mantle.work.ProjectServices.get#UnbilledSummary').parameters({workEffortId: workEffortId, withEntries: true}).call() || {}
if (ec.message.hasError()) return
const row = Array.from(out.projectList || [])[0]
if (!row) { ec.message.addError(L('The project has no billable time to invoice')); return }
if (!row.clientPartyId) { ec.message.addError(L('The project has no client')); return }
if (!row.vendorPartyId) { ec.message.addError(L('The project has no vendor to bill from')); return }
const listOf = (value) => value == null ? [] : (typeof value === 'string' ? value.split(',') : Array.from(value).map(String)).map((id) => id.trim()).filter((id) => id)
const ready = {}
for (const entry of Array.from(row.entryList || [])) if (entry.ready) ready[entry.timeEntryId] = entry
const givenTime = listOf(timeEntryIds)
const givenShares = Array.from(new Set(listOf(milestoneIds)))
if (selection && !givenTime.length && !givenShares.length) { ec.message.addError(L('Select the time or the milestones to invoice')); return }
// the shares due chosen, by milestone
const due = Array.from(row.milestoneDueList || [])
const shareKey = (share) => share.workEffortId + ':' + share.orderId + ':' + share.orderItemSeqId
const chosenShares = []
for (const key of givenShares) {
    const matches = due.filter((share) => shareKey(share) === key || share.workEffortId === key)
    if (!matches.length) { ec.message.addError(ec.resource.expand('Not a milestone share due: ${key}', '', {key})); return }
    for (const share of matches) if (!chosenShares.includes(share)) chosenShares.push(share)
}
let chosen = []
if (givenTime.length) {
    const selected = Array.from(new Set(givenTime))
    const notReady = selected.filter((id) => !ready[id])
    if (notReady.length) { ec.message.addError(ec.resource.expand('Not approved time to invoice: ${ids}', '', {ids: notReady.join(', ')})); return }
    chosen = selected.map((id) => ready[id])
} else if (!selection) chosen = Object.values(ready)
if (!chosen.length && !chosenShares.length) { ec.message.addError(L('No approved time to invoice')); return }
const noRate = chosen.filter((entry) => entry.missingRate)
if (noRate.length) { ec.message.addError(ec.resource.expand('${count} entries have no client rate: set the rates first (${ids})', '', {count: noRate.length,
    ids: noRate.slice(0, 5).map((entry) => entry.timeEntryId).join(', ')})); return }
if (invoiceId) {
    const target = ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', invoiceId).disableAuthz().one()
    if (!target || !Array.from(row.draftInvoiceList || []).some((inv) => inv.invoiceId === invoiceId)) {
        ec.message.addError(ec.resource.expand('Invoice ${invoiceId} is not an open draft of this project to its client', '', {invoiceId})); return }
}
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    // the shares first (a new invoice of them when none is given), then the time on the same invoice
    const byMilestone = {}
    for (const share of chosenShares) (byMilestone[share.workEffortId] || (byMilestone[share.workEffortId] = [])).push(share)
    for (const [milestoneId, shares] of Object.entries(byMilestone)) {
        for (const share of shares) {
            const made = ec.service.sync().name('mantle.account.InvoiceServices.create#MilestoneInvoiceItems').parameters({workEffortId: milestoneId,
                invoiceId: invoiceId || null, orderId: share.orderId, orderItemSeqId: share.orderItemSeqId, invoiceDate: invoiceDate || ec.user.nowTimestamp,
                settlementTermId: settlementTermId || null}).call() || {}
            if (ec.message.hasError()) return
            invoiceId = made.invoiceId
            itemCount += Number(made.invoiceItemCreatedCount || 0)
        }
    }
    if (chosen.length) {
        const made = ec.service.sync().name('mantle.account.InvoiceServices.create#ProjectInvoiceItems').parameters({workEffortId: workEffortId, invoiceId: invoiceId || null,
            approvedOnly: true, billableOnly: true, timeEntryIdList: chosen.map((entry) => entry.timeEntryId), entryGrouping: entryGrouping,
            settlementTermId: settlementTermId || null, invoiceDate: invoiceDate || ec.user.nowTimestamp}).call() || {}
        if (ec.message.hasError()) return
        invoiceId = made.invoiceId
        itemCount += Number(made.invoiceItemCreatedCount || 0)
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
message = ec.resource.expand('Invoice ${invoiceId}: ${count} lines added', '', {invoiceId: invoiceId, count: itemCount})

rowList = []; counts = {}; projectOptions = []; clientOptions = []
// a client (impl-projects.md P10b): its own sent invoices (get#ClientInvoices), read only, with the chips Sent, Overdue, Paid, All
clientView = !!ec.user.userId && ec.user.hasPermission('PROJECT_CLIENT')
const lists = clientView ? ['sent', 'overdue', 'paid', 'all'] : ['drafts', 'toSend', 'sent', 'overdue', 'paid', 'worker', 'all']
if (!lists.includes(list)) list = 'all'
if (!clientView) {
    ec.service.sync().name('ironstone.projects.BillingServices.check#Money').call()
    if (ec.message.hasError()) return
}
const L = (text) => ec.l10n.localize(text)
const map = (clientView ? ec.service.sync().name('ironstone.projects.BillingServices.get#ClientInvoices').parameters({rootWorkEffortId: rootWorkEffortId || null}).call()?.invoiceMap
    : ec.service.sync().name('ironstone.projects.BillingServices.get#InvoiceProjects').parameters({rootWorkEffortId: rootWorkEffortId || null}).call()?.invoiceMap) || {}
const ids = Object.keys(map)
if (!ids.length) { for (const key of lists) counts[key] = 0; return }
const invoices = []
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    for (let i = 0; i < ids.length; i += 1000) for (const row of ec.entity.find('mantle.account.invoice.Invoice').condition('invoiceId', 'in', ids.slice(i, i + 1000)).list()) invoices.push(row)
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
const invoiceDays = ec.resource.script('component://mr-mantle/service/mantle/account/InvoiceWorkflowLib.js')
    .invoiceCalendarDays(invoices.map(inv => inv.invoiceId))
const nowMillis = Number(String(ec.user.nowTimestamp))
const millis = (value) => value == null ? null : Number(String(value))
const unpaidOf = (inv) => toDecimal(inv.unpaidTotal ?? inv.invoiceTotal ?? 0)
const listOf = (inv, kind) => {
    const status = inv.statusId
    const keys = ['all']
    if (kind === 'worker') keys.push('worker')
    if (['InvoiceInProcess', 'InvoiceIncoming', 'InvoiceReceived'].includes(status)) keys.push('drafts')
    if (status === 'InvoiceFinalized') keys.push('toSend')
    if (['InvoiceSent', 'InvoiceAcked'].includes(status)) keys.push('sent')
    if (['InvoicePmtRecvd', 'InvoicePmtSent'].includes(status)) keys.push('paid')
    if (['InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked', 'InvoiceApproved'].includes(status) && millis(inv.dueDate) != null
            && millis(inv.dueDate) < nowMillis && unpaidOf(inv).compare(0) > 0) keys.push('overdue')
    return keys
}
const names = {}
const nameOf = (id) => {
    if (!id) return ''
    if (!(id in names)) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).disableAuthz().one()
        names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
    }
    return names[id]
}
const projectNames = {}
const projectName = (id) => {
    if (!(id in projectNames)) projectNames[id] = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).disableAuthz().one()?.workEffortName || id
    return projectNames[id]
}
const statusText = {}
const statusOf = (id) => {
    if (!id) return ''
    if (!(id in statusText)) statusText[id] = ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id
    return statusText[id]
}
const colors = {InvoiceInProcess: 'blue-grey-6', InvoiceIncoming: 'blue-grey-6', InvoiceReceived: 'blue-grey-6', InvoiceFinalized: 'primary', InvoiceApproved: 'primary',
    InvoiceSent: 'info', InvoiceAcked: 'info', InvoicePmtRecvd: 'positive', InvoicePmtSent: 'positive', InvoiceCancelled: 'grey-6', InvoiceWriteOff: 'warning'}
const kindLabels = {client: 'Client', worker: 'Worker', expense: 'Expense'}
for (const key of lists) counts[key] = 0
const from = fromDate != null ? millis(fromDate) : null
const thru = thruDate != null ? millis(thruDate) : null
const clients = {}, projects = {}
for (const inv of invoices) {
    const entry = map[inv.invoiceId]
    const keys = listOf(inv, entry.kind)
    if (entry.kind === 'client') clients[inv.toPartyId] = nameOf(inv.toPartyId)
    for (const id of entry.projectIds) projects[id] = projectName(id)
    // the find narrows the chips' counts as it does the list
    if (clientPartyId && inv.toPartyId !== clientPartyId) continue
    if (kind && entry.kind !== kind) continue
    const invoiceMillis = millis(inv.invoiceDate)
    const bookDay = invoiceDays[inv.invoiceId]?.invoiceDay
    const findMillis = bookDay ? millis(ec.l10n.parseTimestamp(bookDay + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')) : invoiceMillis
    if (from != null && (findMillis == null || findMillis < from)) continue
    if (thru != null && (findMillis == null || findMillis >= thru)) continue
    for (const key of keys) counts[key]++
    if (!keys.includes(list)) continue
    const uom = inv.currencyUomId || 'USD'
    const overdue = keys.includes('overdue')
    rowList.push({invoiceId: inv.invoiceId, url: '/qapps/Projects/Billing/InvoiceDetail?invoiceId=' + encodeURIComponent(inv.invoiceId), kind: entry.kind,
        kindText: L(kindLabels[entry.kind]), projectText: entry.projectIds.map(projectName).join(', '), projectIds: entry.projectIds,
        fromName: nameOf(inv.fromPartyId), toName: nameOf(inv.toPartyId), invoiceDate: invoiceMillis,
        dateText: invoiceDays[inv.invoiceId]?.invoiceDay || (invoiceMillis == null ? '' : ec.l10n.format(new Date(invoiceMillis), 'MMM d, yyyy')),
        dueText: invoiceDays[inv.invoiceId]?.dueDay || (inv.dueDate == null ? '' : ec.l10n.format(inv.dueDate, 'MMM d, yyyy')), overdue: overdue,
        totalText: ec.l10n.formatCurrency(toDecimal(inv.invoiceTotal ?? 0), uom), unpaidText: ['InvoiceCancelled'].includes(inv.statusId) ? '' : ec.l10n.formatCurrency(unpaidOf(inv), uom),
        statusId: inv.statusId, statusLabel: overdue ? statusOf(inv.statusId) + ' · ' + L('Overdue') : statusOf(inv.statusId),
        statusColor: overdue ? 'negative' : (colors[inv.statusId] || 'grey-8'), description: inv.description || ''})
}
rowList.sort((a, b) => (b.invoiceDate ?? 0) - (a.invoiceDate ?? 0) || String(b.invoiceId).localeCompare(String(a.invoiceId)))
clientOptions = Object.keys(clients).filter((id) => id).map((id) => ({key: id, text: clients[id]})).sort((a, b) => a.text.localeCompare(b.text))
projectOptions = Object.keys(projects).map((id) => ({key: id, text: projects[id]})).sort((a, b) => a.text.localeCompare(b.text))

detail = null
const access = ec.service.sync().name('ironstone.projects.BillingServices.get#InvoiceAccess').parameters({invoiceId: invoiceId, need: 'none'}).call() || {}
if (!access.canView) return
const L = (text) => ec.l10n.localize(text)
const inv = access.invoice
const uom = inv.currencyUomId || 'USD'
const money = (value) => value == null ? '' : ec.l10n.formatCurrency(value, uom)
const hoursText = (value) => value == null ? '' : ec.l10n.format(value, '#,##0.##')
const day = (value) => value == null ? '' : ec.l10n.format(value instanceof Date ? value : new Date(Number(String(value))), 'MMM d, yyyy')
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    const nameOf = (id) => {
        if (!id) return ''
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).one()
        return party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
    }
    const statusOf = (id) => id ? (ec.entity.find('moqui.basic.StatusItem').condition('statusId', id).useCache(true).one()?.description || id) : ''
    const enumOf = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
    const calendarDays = ec.resource.script('component://mr-mantle/service/mantle/account/InvoiceWorkflowLib.js')
        .invoiceCalendarDays([invoiceId])[invoiceId] || {}
    const time = ec.service.sync().name('mantle.account.InvoiceServices.get#InvoiceTimeDetail').parameters({invoiceId: invoiceId}).call() || {}
    const entries = Array.from(time.entryList || [])
    // a client (impl-projects.md P10b) sees the time of a line only on a project that shares its hours with it, as the day,
    // the work item (a shared one by name, any other as other work) and the hours: never who, a rate, an amount or a comment
    const clientView = !!access.clientView
    const shareHours = new Set(Array.from(access.shareHoursProjectIds || []).map(String))
    const shownEntries = clientView ? entries.filter((entry) => entry.rootWorkEffortId && shareHours.has(String(entry.rootWorkEffortId))) : entries
    const sharedItems = new Set()
    if (clientView) {
        const itemIds = Array.from(new Set(shownEntries.map((entry) => entry.workEffortId).filter((id) => id)))
        for (let i = 0; i < itemIds.length; i += 1000) for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', 'in', itemIds.slice(i, i + 1000))
                .selectField('workEffortId').selectField('workEffortTypeEnumId').selectField('visibilityEnumId').list())
            if (row.workEffortTypeEnumId === 'WetProject' || (row.workEffortTypeEnumId === 'WetTask' && ['WevAllUsers', 'WevGeneral'].includes(row.visibilityEnumId)))
                sharedItems.add(row.workEffortId)
    }
    const items = Array.from(ec.entity.find('mantle.account.invoice.InvoiceItem').condition('invoiceId', invoiceId).orderBy('invoiceItemSeqId').list())
    const totalOf = (item) => toDecimal(item.quantity ?? 1).multiply(toDecimal(item.amount ?? 0)).setScale(2, 'HALF_UP')
    const status = inv.statusId
    const isClient = access.kind === 'client'
    const isDraft = status === 'InvoiceInProcess'
    // the milestone shares billed on the lines (WorkEffortBilling; impl-projects.md P8b)
    const milestoneBills = Array.from(ec.entity.find('mantle.work.effort.WorkEffortBilling').condition('invoiceId', invoiceId).list())
    const milestoneRows = milestoneBills.map((web) => {
        const milestone = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', web.workEffortId).one()
        const item = items.find((one) => one.invoiceItemSeqId === web.invoiceItemSeqId)
        const oib = Array.from(ec.entity.find('mantle.order.OrderItemBilling').condition({invoiceId: invoiceId, invoiceItemSeqId: web.invoiceItemSeqId}).list())[0]
        const orderItem = oib ? ec.entity.find('mantle.order.OrderItem').condition({orderId: oib.orderId, orderItemSeqId: oib.orderItemSeqId}).one() : null
        return {invoiceItemSeqId: web.invoiceItemSeqId, workEffortId: web.workEffortId, milestoneName: milestone?.workEffortName || web.workEffortId,
            milestoneUrl: '/qapps/Projects/Projects/MilestoneDetail?workEffortId=' + encodeURIComponent(web.workEffortId),
            reachedText: milestone?.actualCompletionDate != null ? day(milestone.actualCompletionDate) : '',
            percentText: web.percentage != null ? ec.l10n.format(web.percentage, '#,##0.##') + '%' : '',
            lineText: oib ? oib.orderId + ' ' + oib.orderItemSeqId + (orderItem?.itemDescription ? ' · ' + orderItem.itemDescription : '') : '',
            orderUrl: oib && !clientView ? '/qapps/Projects/Billing/OrderDetail?orderId=' + encodeURIComponent(oib.orderId) : null,
            amountText: item ? money(totalOf(item)) : ''}
    })
    const itemRows = items.map((item) => {
        const itemEntries = shownEntries.filter((entry) => (entry.invoiceItemSeqId || '') === item.invoiceItemSeqId)
        const itemMilestone = milestoneRows.find((one) => one.invoiceItemSeqId === item.invoiceItemSeqId)
        const hours = itemEntries.reduce((total, entry) => total.add(entry.hours), toDecimal(0))
        return {invoiceItemSeqId: item.invoiceItemSeqId, typeText: enumOf(item.itemTypeEnumId), description: item.description || '',
            itemDateText: item.itemDate != null ? day(item.itemDate) : '', quantityText: item.quantity == null ? '1' : ec.l10n.format(item.quantity, '#,##0.##'),
            amountText: money(toDecimal(item.amount ?? 0)), totalText: money(totalOf(item)), entryCount: itemEntries.length,
            timeText: itemEntries.length ? ec.resource.expand('${count} entries, ${hours} h', '', {count: itemEntries.length, hours: hoursText(hours)})
                : itemMilestone ? ec.resource.expand('Milestone ${name}, reached ${date}', '', {name: itemMilestone.milestoneName,
                    date: itemMilestone.reachedText}) : '',
            isMilestone: !!itemMilestone,
            canRemove: !clientView && isClient && isDraft}
    })
    const entryRows = clientView ? shownEntries.map((entry) => {
        const shared = !!entry.workEffortId && sharedItems.has(entry.workEffortId)
        return {invoiceItemSeqId: entry.invoiceItemSeqId || '', dayText: entry.fromDate == null ? '' : ec.l10n.format(new Date(entry.fromDate), 'EEE MMM d'),
            itemText: !shared ? L('Other work') : entry.workEffortId === entry.rootWorkEffortId ? entry.workEffortName : entry.workEffortId + ' ' + entry.workEffortName,
            itemUrl: shared && entry.workEffortId !== entry.rootWorkEffortId ? '/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=' + encodeURIComponent(entry.workEffortId) : null,
            hoursText: hoursText(entry.hours)}
    }) : entries.map((entry) => ({timeEntryId: entry.timeEntryId, invoiceItemSeqId: entry.invoiceItemSeqId || '', personName: entry.personName,
        dayText: entry.fromDate == null ? '' : ec.l10n.format(new Date(entry.fromDate), 'EEE MMM d'),
        itemText: entry.workEffortId ? (entry.workEffortId === entry.rootWorkEffortId ? entry.workEffortName : entry.workEffortId + ' ' + entry.workEffortName) : '',
        itemUrl: entry.workEffortId && entry.workEffortId !== entry.rootWorkEffortId ? '/qapps/Projects/WorkItems/WorkItemDetail?workEffortId=' + encodeURIComponent(entry.workEffortId) : null,
        hoursText: hoursText(entry.hours), rateText: entry.rate == null ? '' : money(entry.rate), amountText: entry.amount == null ? '' : money(entry.amount),
        comments: entry.comments || ''}))
    const payments = Array.from(ec.entity.find('mantle.account.payment.PaymentApplication').condition('invoiceId', invoiceId).list()).map((pa) => ({
        paymentId: pa.paymentId || pa.toInvoiceId || '', amountText: money(toDecimal(pa.amountApplied ?? 0)), dateText: pa.appliedDate != null ? day(pa.appliedDate) : ''}))
    const projects = Array.from(access.projectIds || []).map((id) => ({workEffortId: id, name: ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).one()?.workEffortName || id,
        url: '/qapps/Projects/Projects/ProjectDetail?workEffortId=' + encodeURIComponent(id)}))
    // the address to send to: the client's billing email, its billing contact's on the project, else its primary
    let sendTo = ''
    if (isClient && !clientView && inv.toPartyId) {
        const billing = Array.from(ec.entity.find('mantle.party.contact.PartyContactMechInfo').condition('partyId', inv.toPartyId)
                .condition('contactMechPurposeId', 'EmailBilling').conditionDate('fromDate', 'thruDate', null).list())[0]
        sendTo = billing?.infoString || ''
        if (!sendTo && projects.length) {
            const contact = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', projects[0].workEffortId)
                    .condition('roleTypeId', 'ClientBilling').conditionDate('fromDate', 'thruDate', null).list())[0]
            if (contact) sendTo = ec.service.sync().name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameters({partyId: contact.partyId}).call()?.emailAddress || ''
        }
        if (!sendTo) sendTo = ec.service.sync().name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameters({partyId: inv.toPartyId}).call()?.emailAddress || ''
    }
    const total = toDecimal(inv.invoiceTotal ?? 0)
    const unpaid = toDecimal(inv.unpaidTotal ?? inv.invoiceTotal ?? 0)
    const overdue = ['InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked'].includes(status) && inv.dueDate != null
            && Number(String(inv.dueDate)) < Number(String(ec.user.nowTimestamp)) && unpaid.compare(0) > 0
    const term = inv.settlementTermId ? ec.entity.find('mantle.account.invoice.SettlementTerm').condition('settlementTermId', inv.settlementTermId).useCache(true).one() : null
    const firstProject = projects[0]?.workEffortId
    const timeDetail = firstProject ? (ec.service.sync().name('mantle.work.ProjectServices.get#ProjectSettings').parameters({workEffortId: firstProject}).call()?.settings?.WstTimeDetail !== 'N') : true
    detail = {invoiceId: invoiceId, kind: access.kind, kindText: L({client: 'Client invoice', worker: 'Worker invoice', expense: 'Expense invoice'}[access.kind] || 'Invoice'),
        statusId: status, statusLabel: statusOf(status), isDraft: isDraft, isClient: isClient, overdue: overdue,
        fromPartyId: inv.fromPartyId, fromName: nameOf(inv.fromPartyId), toPartyId: inv.toPartyId, toName: nameOf(inv.toPartyId),
        invoiceDateText: calendarDays.invoiceDay || day(inv.invoiceDate), invoiceDateValue: calendarDays.invoiceDay || (inv.invoiceDate == null ? '' : ec.l10n.format(inv.invoiceDate, 'yyyy-MM-dd')),
        dueDateText: calendarDays.dueDay || day(inv.dueDate), termText: term ? (term.description || term.settlementTermId) : '', settlementTermId: inv.settlementTermId || '',
        referenceNumber: inv.referenceNumber || '', description: inv.description || '', invoiceMessage: inv.invoiceMessage || '',
        currencyUomId: uom, totalText: money(total), unpaidText: money(unpaid), paidText: money(total.subtract(unpaid)),
        hoursText: hoursText(clientView ? shownEntries.reduce((sum, entry) => sum.add(entry.hours), toDecimal(0)) : (time.hours ?? toDecimal(0))),
        timeAmountText: clientView ? '' : money(time.amount ?? toDecimal(0)), clientView: clientView, itemRows: itemRows, entryRows: entryRows, milestoneRows: milestoneRows, payments: payments, projects: projects,
        projectText: projects.map((project) => project.name).join(', '), sendTo: sendTo, timeDetail: timeDetail,
        printUrl: '/apps/Projects/Billing/InvoicePrint?renderMode=html-print&invoiceId=' + encodeURIComponent(invoiceId),
        pdfUrl: '/fop/apps/Projects/Billing/InvoicePrint?invoiceId=' + encodeURIComponent(invoiceId) + '&filename=Invoice-' + encodeURIComponent(invoiceId) + '.pdf',
        canApprove: !clientView && isClient && isDraft && items.length > 0,
        canSend: !clientView && isClient && ['InvoiceInProcess', 'InvoiceFinalized', 'InvoiceSent', 'InvoiceAcked'].includes(status) && items.length > 0,
        sendAgain: ['InvoiceSent', 'InvoiceAcked'].includes(status), canResume: !clientView && isClient && status === 'InvoiceFinalized',
        canCancel: !clientView && isClient && ['InvoiceInProcess', 'InvoiceFinalized'].includes(status), canEdit: !clientView && isClient && isDraft,
        stageStatusIds: ['InvoiceInProcess', 'InvoiceFinalized', 'InvoiceSent', 'InvoicePmtRecvd']}
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

set.from:
{invoiceId:invoiceId, organizationPartyId:access.invoice.fromPartyId,
                lastUpdatedStamp:access.invoice.lastUpdatedStamp, settlementTermId:settlementTermId || null,
                referenceNumber:referenceNumber || null, description:description || null, invoiceMessage:invoiceMessage || null}

actions.script:
rowList = []; counts = {}
const rateAccess = ec.service.sync().name('ironstone.projects.BillingServices.check#RateAccess').call() || {}
if (ec.message.hasError()) return
const purposes = ['RaprClient', 'RaprVendor', 'RaprCost'].filter((purpose) => rateAccess[{RaprClient: 'client', RaprVendor: 'worker', RaprCost: 'cost'}[purpose]])
for (const purpose of purposes) counts[purpose] = 0
const L = (text) => ec.l10n.localize(text)
const cf = ec.entity.conditionFactory
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const all = !!vis.allProjects
const visible = Array.from(vis.visibleProjectIds || [])
const nowMillis = Number(String(ec.user.nowTimestamp))
let on = null
if (effectiveOn) {
    const parsed = ec.l10n.parseTimestamp(String(effectiveOn).substring(0, 10) + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
    if (parsed != null) on = Number(String(parsed))
}
const conds = [cf.makeCondition('ratePurposeEnumId', 'in', purposes)]
// a costing rate names no project or person; an employee's pay rate is payroll's on any project
if (!all && !rateAccess.payOnly) conds.push(cf.makeCondition([cf.makeCondition('workEffortId', 'is-null', null),
    cf.makeCondition('workEffortId', 'in', visible.length ? visible : ['_NA_'])], 'or'))
if (rateAccess.payOnly) conds.push(cf.makeCondition([cf.makeCondition('ratePurposeEnumId', 'equals', 'RaprCost'),
    cf.makeCondition('partyId', 'is-not-null', null)], 'or'))
if (rootWorkEffortId) conds.push(cf.makeCondition('workEffortId', 'equals', rootWorkEffortId))
if (partyId) conds.push(cf.makeCondition('partyId', 'equals', partyId))
if (workTypeEnumId) conds.push(cf.makeCondition('workTypeEnumId', 'equals', workTypeEnumId))
if (emplPositionClassId) conds.push(cf.makeCondition('emplPositionClassId', 'equals', emplPositionClassId))
if (rateTypeEnumId) conds.push(cf.makeCondition('rateTypeEnumId', 'equals', rateTypeEnumId))
const rows = []
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    for (const rate of ec.entity.find('mantle.humanres.rate.RateAmount').condition(cf.makeCondition(conds, 'and')).orderBy('workEffortId').orderBy('partyId')
            .orderBy('workTypeEnumId').orderBy('-fromDate').limit(5000).list()) rows.push(rate)
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
const enumText = (id) => id ? (ec.entity.find('moqui.basic.Enumeration').condition('enumId', id).useCache(true).one()?.description || id) : ''
// the labor costing rates the user reads: the shared ones and those of their organizations (mantle.humanres.RateServices
// find#CostingRates' scope; an organization's row of another organization is left out)
const costIds = purposes.includes('RaprCost') ? new Set(Array.from(ec.service.sync().name('mantle.humanres.RateServices.find#CostingRates')
        .parameters({showEnded: true}).call()?.rateList || []).map((row) => row.rateAmountId)) : new Set()
ec.message.clearErrors()
// an employee's worker pay rate is pay: read with PAYROLL_VIEW, changed with PAYROLL_EDIT, asked once for the people
const pay = ec.service.sync().name('mantle.humanres.EmploymentServices.get#PayRateAccess').parameters({partyIdList: Array.from(new Set(rows
        .filter((rate) => rate.ratePurposeEnumId === 'RaprVendor' && rate.partyId).map((rate) => rate.partyId)))}).disableAuthz().call() || {}
const payHidden = new Set(Array.from(pay.hiddenPartyIds || [])), payLocked = new Set(Array.from(pay.lockedPartyIds || []))
// payroll without money: the employees of the user's People employers alone (get#PayrollEmployees)
const employees = new Set(rateAccess.payOnly ? Array.from(ec.service.sync().name('ironstone.projects.BillingServices.get#PayrollEmployees')
        .parameters({partyIdList: rows.filter((rate) => rate.ratePurposeEnumId === 'RaprVendor' && rate.partyId).map((rate) => rate.partyId)})
        .call()?.employeePartyIds || []) : Array.from(pay.employeePartyIds || []))
const names = {}
const nameOf = (id) => {
    if (!id) return ''
    if (!(id in names)) {
        const party = ec.entity.find('mantle.party.PartyDetail').condition('partyId', id).disableAuthz().one()
        names[id] = party ? (party.organizationName || [party.firstName, party.lastName].filter((part) => part).join(' ') || party.pseudoId || id) : id
    }
    return names[id]
}
const projects = {}
const projectName = (id) => {
    if (!id) return ''
    if (!(id in projects)) projects[id] = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', id).disableAuthz().one()?.workEffortName || id
    return projects[id]
}
const positions = {}
const positionOf = (id) => {
    if (!id) return ''
    if (!(id in positions)) positions[id] = ec.entity.find('mantle.humanres.position.EmplPositionClass').condition('emplPositionClassId', id).useCache(true).one()?.title || id
    return positions[id]
}
const millis = (value) => value == null ? null : Number(String(value))
for (const rate of rows) {
    const from = millis(rate.fromDate), thru = millis(rate.thruDate)
    const ended = thru != null && thru <= nowMillis
    const coming = from != null && from > nowMillis
    if (on != null) { if ((from != null && from > on) || (thru != null && thru <= on)) continue }
    else if (ended && !showEnded) continue
    // payroll without money reads the employees' pay rates, not a contractor's; a costing rate is no person's
    if (rateAccess.payOnly && rate.ratePurposeEnumId === 'RaprVendor' && !employees.has(rate.partyId)) continue
    if (rate.ratePurposeEnumId === 'RaprCost' && (rate.partyId || rate.workEffortId || !costIds.has(rate.rateAmountId))) continue
    counts[rate.ratePurposeEnumId] = (counts[rate.ratePurposeEnumId] || 0) + 1
    if (rate.ratePurposeEnumId !== ratePurposeEnumId) continue
    const uom = rate.rateCurrencyUomId || 'USD'
    const isPay = rate.ratePurposeEnumId === 'RaprVendor' && !!rate.partyId
    const hidden = isPay && payHidden.has(rate.partyId)
    rowList.push({rateAmountId: rate.rateAmountId, ratePurposeEnumId: rate.ratePurposeEnumId, rateTypeEnumId: rate.rateTypeEnumId, rateTypeText: enumText(rate.rateTypeEnumId),
        workEffortId: rate.workEffortId || null, projectName: rate.workEffortId ? projectName(rate.workEffortId) : L('Any project'),
        projectUrl: rate.workEffortId && !rateAccess.payOnly ? '/qapps/Projects/Projects/ProjectDetail?workEffortId=' + encodeURIComponent(rate.workEffortId) : null,
        partyId: rate.partyId || null, personName: rate.partyId ? nameOf(rate.partyId) : L('Anyone'), workTypeEnumId: rate.workTypeEnumId || null,
        workTypeText: rate.workTypeEnumId ? enumText(rate.workTypeEnumId) : L('Any work'), emplPositionClassId: rate.emplPositionClassId || null,
        positionText: positionOf(rate.emplPositionClassId), fromText: from == null ? '' : ec.l10n.format(new Date(from), 'MMM d, yyyy'),
        thruText: thru == null ? '' : ec.l10n.format(new Date(thru), 'MMM d, yyyy'),
        fromValue: from == null ? '' : ec.l10n.format(new Date(from), 'yyyy-MM-dd'), thruValue: thru == null ? '' : ec.l10n.format(new Date(thru), 'yyyy-MM-dd'),
        rateAmount: hidden ? null : rate.rateAmount, amountValue: hidden || rate.rateAmount == null ? '' : String(toDecimal(rate.rateAmount).setScale(2, 'HALF_UP')),
        amountText: hidden ? L('Set by payroll') : ec.l10n.formatCurrency(toDecimal(rate.rateAmount ?? 0), uom) + (rate.timePeriodUomId === 'OTH_ea' ? ' / ' + L('piece') : ' / h'), currencyUomId: uom,
        stateText: ended ? L('Ended') : coming ? L('From') + ' ' + ec.l10n.format(new Date(from), 'MMM d') : L('Current'), ended: ended, coming: coming,
        // a no-charge rate on no project and no person is the seed that bills no-charge time at nothing: kept as it is
        canChange: !ended && rate.ratePurposeEnumId !== 'RaprCost' && !(rate.rateTypeEnumId === 'RatpNoCharge' && !rate.workEffortId && !rate.partyId)
            && !(isPay && payLocked.has(rate.partyId))})
}

const L = (text) => ec.l10n.localize(text)
const rateAccess = ec.service.sync().name('ironstone.projects.BillingServices.check#RateAccess').call() || {}
if (ec.message.hasError()) return
const text = String(rateAmount ?? '').trim().replace(/,/g, '')
if (!/^\d+(\.\d{1,4})?$/.test(text)) { ec.message.addError(L('The rate is an amount, 0 or more')); return }
const day = (value, label) => {
    if (value == null || String(value).trim() === '') return null
    const parsed = ec.l10n.parseTimestamp(String(value).trim().substring(0, 10) + ' 00:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS')
    if (parsed == null) ec.message.addError(ec.resource.expand('${label} is a day, yyyy-MM-dd', '', {label: L(label)}))
    return parsed
}
const from = day(fromDate, 'From'), thru = day(thruDate, 'Thru')
if (ec.message.hasError()) return
if (from != null && thru != null && Number(String(thru)) <= Number(String(from))) { ec.message.addError(L('Thru is after from')); return }
const vis = ec.service.sync().name('mantle.work.ProjectServices.get#VisibleProjectInfo').call() || {}
const sees = (id) => !id || vis.allProjects || Array.from(vis.visibleProjectIds || []).includes(id)
// an employee's worker pay rate is pay: payroll's to set (PAYROLL_EDIT)
const payLocked = (purpose, id) => purpose === 'RaprVendor' && !!id && Array.from(ec.service.sync().name('mantle.humanres.EmploymentServices.get#PayRateAccess')
        .parameters({partyIdList: [id]}).disableAuthz().call()?.lockedPartyIds || []).includes(id)
// payroll without money: the pay rate of an employee of the user's People employers only (People P10)
const isEmployee = (id) => !!id && Array.from(ec.service.sync().name('ironstone.projects.BillingServices.get#PayrollEmployees')
        .parameters({partyIdList: [id]}).call()?.employeePartyIds || []).includes(id)
const payOnlyRefused = (purpose, id, project) => rateAccess.payOnly && (purpose !== 'RaprVendor' || !isEmployee(id) || !!project)
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (rateAmountId) {
        const rate = ec.entity.find('mantle.humanres.rate.RateAmount').condition('rateAmountId', rateAmountId).one()
        if (!rate || !['RaprClient', 'RaprVendor'].includes(rate.ratePurposeEnumId) || (!rateAccess.payOnly && !sees(rate.workEffortId))
                || (rateAccess.payOnly && (rate.ratePurposeEnumId !== 'RaprVendor' || !isEmployee(rate.partyId)))) {
            ec.message.addError(ec.resource.expand('Rate ${rateAmountId} is not available', '', {rateAmountId})); return }
        if (payLocked(rate.ratePurposeEnumId, rate.partyId)) { ec.message.addError(L('The worker pay rate of an employee is their pay: only payroll sets it')); return }
        ec.service.sync().name('mantle.humanres.RateServices.update#RateAmount').parameters({rateAmountId: rateAmountId, rateAmount: toDecimal(text),
            fromDate: from ?? rate.fromDate, thruDate: thru}).call()
        if (!ec.message.hasError()) message = L('Rate saved')
        return
    }
    if (!['RaprClient', 'RaprVendor'].includes(ratePurposeEnumId)) { ec.message.addError(L('A rate is for client billing or worker pay')); return }
    if (payOnlyRefused(ratePurposeEnumId, partyId, workEffortId)) { ec.message.addError(L('Payroll sets the pay rate of an employee, on no project')); return }
    if (workEffortId) {
        const project = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
        if (!project || project.workEffortTypeEnumId !== 'WetProject' || !sees(workEffortId)) {
            ec.message.addError(ec.resource.expand('Project ${workEffortId} is not available', '', {workEffortId})); return }
    }
    const type = rateTypeEnumId || 'RatpStandard'
    if (ec.entity.find('moqui.basic.Enumeration').condition('enumId', type).useCache(true).one()?.enumTypeId !== 'RateType') { ec.message.addError(L('Not a rate type')); return }
    if (workTypeEnumId && ec.entity.find('moqui.basic.Enumeration').condition('enumId', workTypeEnumId).useCache(true).one()?.enumTypeId !== 'WorkType') {
        ec.message.addError(L('Not a work type')); return }
    if (partyId && !ec.entity.find('mantle.party.Party').condition('partyId', partyId).one()) { ec.message.addError(ec.resource.expand('No party ${partyId}', '', {partyId})); return }
    if (payLocked(ratePurposeEnumId, partyId)) { ec.message.addError(L('The worker pay rate of an employee is their pay: only payroll sets it')); return }
    rateAmountId = ec.service.sync().name('mantle.humanres.RateServices.create#RateAmount').parameters({ratePurposeEnumId: ratePurposeEnumId, rateTypeEnumId: type,
        workEffortId: workEffortId || null, partyId: partyId || null, emplPositionClassId: emplPositionClassId || null, workTypeEnumId: workTypeEnumId || null,
        fromDate: from ?? ec.user.nowTimestamp, thruDate: thru, rateAmount: toDecimal(text), timePeriodUomId: 'TF_hr',
        rateCurrencyUomId: rateCurrencyUomId || ec.user.getPreference('CurrencyDefault') || 'USD'}).call()?.rateAmountId
    if (!ec.message.hasError()) message = L('Rate added')
