        statusText: statusText(inv.statusId), totalText: cash(inv.invoiceTotal ?? 0)})) : []
    const projectRows = access.projectIds.map((id) => ({workEffortId: id, name: projectNames[id], url: '/qapps/Projects/Projects/ProjectDetail/Money?workEffortId=' + encodeURIComponent(id)}))
    const single = access.projectIds.length === 1 ? access.projectIds[0] : null
    const estimateId = single ? ec.entity.find('mantle.work.effort.WorkEffortSetting').condition('workEffortId', single).condition('settingTypeEnumId', 'WstEstimateMilestone').one()?.settingValue : null
    const estimate = estimateId ? ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: estimateId, need: 'none'}).call()?.gate : null
    detail = {orderId: orderId, orderName: header.orderName || '', statusId: header.statusId, statusText: statusText(header.statusId),
        customerName: nameOf(part?.customerPartyId), vendorName: nameOf(part?.vendorPartyId), customerPartyId: part?.customerPartyId || null,
        entryDateText: day(header.entryDate), placedDateText: day(header.placedDate), approvedDateText: day(header.approvedDate),
        totalText: cash(header.grandTotal ?? total), currencyUomId: uom, lineRows: lineRows, shareRows: shareRows, invoiceRows: invoiceRows, projectRows: projectRows,
        projectId: single, projectName: single ? projectNames[single] : '', canManage: !!access.canManage,
        canSendEstimate: !!single && !!access.canManage && ['OrderOpen', 'OrderProposed'].includes(header.statusId),
        estimateText: estimate?.awaiting ? L('The estimate waits for the client\'s approval') : estimate?.approved ? L('The client approved the estimate') : '',
        estimateMilestoneUrl: estimateId ? '/qapps/Projects/Projects/MilestoneDetail?workEffortId=' + encodeURIComponent(estimateId) : null,
        printUrl: single ? '/apps/Projects/Projects/EstimatePrint?renderMode=html-print&workEffortId=' + encodeURIComponent(single) : null,
        stageStatusIds: ['OrderOpen', 'OrderProposed', 'OrderPlaced', 'OrderApproved', 'OrderCompleted']}
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }

ec.service.sync().name('ironstone.projects.BillingServices.check#Money').call()
if (ec.message.hasError()) return
ec.service.sync().name('ironstone.projects.ProjectServices.get#ProjectAccess').parameters({workEffortId: workEffortId, need: 'manage'}).call()
if (ec.message.hasError()) return
const wasDisabled = ec.artifactExecution.disableAuthz()
let out = {}
try {
    // the Projects managers manage every project they see (get#ProjectAccess): Mantle checks MILESTONE_APPROVE for them
    out = ec.service.sync().name('mantle.work.ProjectServices.send#EstimateForApproval').parameters({workEffortId: workEffortId, depth: depth, comments: comments || null}).call() || {}
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (ec.message.hasError()) return
milestoneId = out.milestoneId
const approver = ec.service.sync().name('mantle.work.ProjectServices.get#MilestoneApprovalAccess').parameters({workEffortId: milestoneId, need: 'none'}).call()?.gate?.approverName || ''
message = ec.resource.expand('Estimate sent for approval to ${approver}', '', {approver})
